/* adi.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "adi.h"


/* Array initialization.
 *
 * Minor optimization:
 *  - Hoist the common term (i + n) out of the inner loop.
 *  - Use a row pointer to improve locality and reduce indexing overhead.
 *  - Keep the division exactly as in the original code (no 1/x transforms),
 *    preserving strict IEEE-754 semantics.
 */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(u,N,N,n,n))
{
  int i, j;
  const DATA_TYPE denom = (DATA_TYPE)n;

  for (i = 0; i < n; i++)
  {
    DATA_TYPE *restrict u_row = u[i];
    const int tmp = i + n; /* common integer term reused below */

    for (j = 0; j < n; j++)
    {
      /* Original formula: (DATA_TYPE)(i + n - j) / n */
      u_row[j] = (DATA_TYPE)(tmp - j) / denom;
    }
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */

static 
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(u,N,N,n,n)) 

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("u");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, u[i][j]);
    }
  POLYBENCH_DUMP_END("u");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
/* Based on a Fortran code fragment from Figure 5 of
 * "Automatic Data and Computation Decomposition on Distributed Memory Parallel Computers"
 * by Peizong Lee and Zvi Meir Kedem, TOPLAS, 2002
 *
 * Optimizations applied:
 *  - Precompute all scalar constants once (outside the time loop).
 *  - Introduce local constants for 1, 0, and 2, and for (1 + 2a), (1 + 2d).
 *  - Use local integer copies of loop bounds (_PB_N, _PB_TSTEPS) to avoid
 *    repeated macro expansion.
 *  - Use row pointers (p_row, q_row, u_row) to improve cache locality and
 *    reduce address computation cost.
 *  - Factor out the common denominator in each tridiagonal step to avoid
 *    recomputing (a*p[i][j-1] + b) / (d*p[i][j-1] + e).
 *    We still perform two divisions per iteration (no division-to-multiply
 *    transformation) to preserve strict IEEE-754 semantics.
 *  - Parallelize the sweeps over `i` with OpenMP `parallel for`. Each `i`
 *    iteration touches disjoint rows/columns, so there are no loop-carried
 *    dependencies across `i`. If compiled without OpenMP support, the pragmas
 *    are ignored and the code remains correct and sequential.
 */
static
void kernel_adi[[gnu::flatten, gnu::noinline]](int tsteps, int n,
		DATA_TYPE POLYBENCH_2D(u,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(v,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(p,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(q,N,N,n,n))
{
  /* Use PolyBench’s possibly-adjusted loop bounds. */
  const int n_       = _PB_N;
  const int tsteps_  = _PB_TSTEPS;

  /* Basic scalar constants, evaluated once. */
  const DATA_TYPE one  = SCALAR_VAL(1.0);
  const DATA_TYPE zero = SCALAR_VAL(0.0);
  const DATA_TYPE two  = SCALAR_VAL(2.0);

  /* Discretization coefficients. These are invariant across all time steps. */
  const DATA_TYPE DX  = one / (DATA_TYPE)n_;
  const DATA_TYPE DY  = one / (DATA_TYPE)n_;
  const DATA_TYPE DT  = one / (DATA_TYPE)tsteps_;
  const DATA_TYPE B1  = SCALAR_VAL(2.0);
  const DATA_TYPE B2  = one;
  const DATA_TYPE mul1 = B1 * DT / (DX * DX);
  const DATA_TYPE mul2 = B2 * DT / (DY * DY);

  const DATA_TYPE a = -mul1 / two;
  const DATA_TYPE b =  one + mul1;
  const DATA_TYPE c =  a;
  const DATA_TYPE d = -mul2 / two;
  const DATA_TYPE e =  one + mul2;
  const DATA_TYPE f =  d;

  /* Frequently used combinations. */
  const DATA_TYPE one_plus_2d = one + two * d;
  const DATA_TYPE one_plus_2a = one + two * a;

  int t;

#pragma scop
  /* Time-stepping loop.
   *
   * We change the bounds from (t = 1; t <= _PB_TSTEPS; t++)
   * to (t = 0; t < tsteps_; ++t). Since `t` is not used inside,
   * this only changes the loop index values, not the number of
   * iterations, so the semantics are preserved.
   */
  for (t = 0; t < tsteps_; ++t)
  {
    /* ------------------------------------------------------------------ */
    /* Column sweep: for each interior column i, solve a tridiagonal
     * system along the j-direction to update v(*, i).
     *
     * Dependencies are along j within each column, but there is no
     * dependency across different columns (different `i`). Therefore
     * we safely parallelize this outer loop over `i`.
     * ------------------------------------------------------------------ */
    #pragma omp parallel for schedule(static)
    for (int i = 1; i < n_ - 1; ++i)
    {
      DATA_TYPE *restrict p_row = p[i];
      DATA_TYPE *restrict q_row = q[i];

      /* Top boundary conditions for column i. */
      v[0][i]  = one;
      p_row[0] = zero;
      q_row[0] = one; /* equals v[0][i] */

      /* Forward sweep along the column (increasing j). */
      for (int j = 1; j < n_ - 1; ++j)
      {
        const DATA_TYPE p_im1 = p_row[j - 1];
        const DATA_TYPE denom = a * p_im1 + b;

        /* Same two divisions as in the original code, but with
         * the shared denominator factored out into `denom`. */
        p_row[j] = -c / denom;

        const DATA_TYPE q_im1   = q_row[j - 1];
        const DATA_TYPE u_j_im1 = u[j][i - 1];
        const DATA_TYPE u_j_i   = u[j][i];
        const DATA_TYPE u_j_ip1 = u[j][i + 1];

        const DATA_TYPE num =
            (-d * u_j_im1) +
            (one_plus_2d * u_j_i) -
            (f * u_j_ip1) -
            (a * q_im1);

        q_row[j] = num / denom;
      }

      /* Bottom boundary condition for column i. */
      v[n_ - 1][i] = one;

      /* Backward substitution along the column (decreasing j). */
      for (int j = n_ - 2; j > 0; --j)
      {
        v[j][i] = p_row[j] * v[j + 1][i] + q_row[j];
      }
    }

    /* ------------------------------------------------------------------ */
    /* Row sweep: for each interior row i, solve a tridiagonal system
     * along the j-direction to update u(i, *).
     *
     * Dependencies are along j within each row, but there is no
     * dependency across different rows (different `i`). Therefore
     * we safely parallelize this outer loop over `i` as well.
     * ------------------------------------------------------------------ */
    #pragma omp parallel for schedule(static)
    for (int i = 1; i < n_ - 1; ++i)
    {
      DATA_TYPE *restrict p_row = p[i];
      DATA_TYPE *restrict q_row = q[i];
      DATA_TYPE *restrict u_row = u[i];

      /* Left boundary conditions for row i. */
      u_row[0] = one;
      p_row[0] = zero;
      q_row[0] = one; /* equals u[i][0] */

      /* Forward sweep along the row (increasing j). */
      for (int j = 1; j < n_ - 1; ++j)
      {
        const DATA_TYPE p_im1 = p_row[j - 1];
        const DATA_TYPE denom = d * p_im1 + e;

        p_row[j] = -f / denom;

        const DATA_TYPE q_im1  = q_row[j - 1];
        const DATA_TYPE v_im1j = v[i - 1][j];
        const DATA_TYPE v_ij   = v[i][j];
        const DATA_TYPE v_ip1j = v[i + 1][j];

        const DATA_TYPE num =
            (-a * v_im1j) +
            (one_plus_2a * v_ij) -
            (c * v_ip1j) -
            (d * q_im1);

        q_row[j] = num / denom;
      }

      /* Right boundary condition for row i. */
      u_row[n_ - 1] = one;

      /* Backward substitution along the row (decreasing j). */
      for (int j = n_ - 2; j > 0; --j)
      {
        u_row[j] = p_row[j] * u_row[j + 1] + q_row[j];
      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(u, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(v, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(p, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(q, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(u));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_adi (tsteps, n, POLYBENCH_ARRAY(u), POLYBENCH_ARRAY(v),
              POLYBENCH_ARRAY(p), POLYBENCH_ARRAY(q));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(u)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(u);
  POLYBENCH_FREE_ARRAY(v);
  POLYBENCH_FREE_ARRAY(p);
  POLYBENCH_FREE_ARRAY(q);

  return 0;
}
