        DATA_TYPE *restrict p_i = p_[i];
        DATA_TYPE *restrict q_i = q_[i];

        /* Boundary conditions for this column. */
        v_[0][i] = one;
        p_i[0]   = zero;
        q_i[0]   = one;

        /* Forward sweep along j (tridiagonal solve). */
        for (j = 1; j < _PB_N - 1; j++)
        {
          /* Common denominator for p and q, computed once per j. */
          const DATA_TYPE denom     = a * p_i[j-1] + b;
          const DATA_TYPE inv_denom = one / denom; /* replaces two divisions */

          /* Neighboring points of u along the i-direction. */
          const DATA_TYPE u_j_im1 = u_[j][i-1];
          const DATA_TYPE u_j_i   = u_[j][i];
          const DATA_TYPE u_j_ip1 = u_[j][i+1];

          /* p update: -c / denom. */
          p_i[j] = neg_c * inv_denom;

          /* q update, using precomputed coefficients. */
          const DATA_TYPE rhs =
            neg_d       * u_j_im1 +
            one_plus_2d * u_j_i   +
            neg_f       * u_j_ip1 +
            neg_a       * q_i[j-1];

          q_i[j] = rhs * inv_denom;
        }

        /* Backward substitution for this column. */
        v_[_PB_N-1][i] = one;
        for (j = _PB_N - 2; j >= 1; j--)
        {
          v_[j][i] = p_i[j] * v_[j+1][i] + q_i[j];
        }
      } /* end column sweep over i */

      /*--------------------------------------------------------------*
       * Row sweep: for each row i, solve a tridiagonal system
       * in the j-direction to update u(i, :) from v(i-1..i+1, :).
       *--------------------------------------------------------------*/
#pragma omp for schedule(static)
      for (i = 1; i < _PB_N - 1; i++)
      {
        DATA_TYPE *restrict p_i = p_[i];
        DATA_TYPE *restrict q_i = q_[i];
        DATA_TYPE *restrict u_i = u_[i];

        /* Boundary conditions for this row. */
        u_i[0] = one;
        p_i[0] = zero;
        q_i[0] = one;

        /* Forward sweep along j (tridiagonal solve). */
        for (j = 1; j < _PB_N - 1; j++)
        {
          const DATA_TYPE denom     = d * p_i[j-1] + e;
          const DATA_TYPE inv_denom = one / denom;

          /* p update: -f / denom. */
          p_i[j] = neg_f * inv_denom;

          /* Neighboring points of v along the i-direction. */
          const DATA_TYPE v_im1_j = v_[i-1][j];
          const DATA_TYPE v_i_j   = v_[i][j];
          const DATA_TYPE v_ip1_j = v_[i+1][j];

          /* q update, using precomputed coefficients. */
          const DATA_TYPE rhs =
            neg_a       * v_im1_j +
            one_plus_2a * v_i_j   +
            neg_c       * v_ip1_j +
            neg_d       * q_i[j-1];

          q_i[j] = rhs * inv_denom;
        }

        /* Backward substitution for this row. */
        u_i[_PB_N-1] = one;
        for (j = _PB_N - 2; j >= 1; j--)
        {
          u_i[j] = p_i[j] * u_i[j+1] + q_i[j];
        }
      } /* end row sweep over i */
    }   /* end time loop */
  }     /* end OpenMP parallel region */

#pragma endscop
}


