          v_[j][i] = p_[i][j] * v_[j+1][i] + q_[i][j];
        }
      } /* end Column Sweep over i */

      /*----------------------------------------------------------*
       * Row Sweep
       *----------------------------------------------------------*/
#pragma omp for schedule(static)
      for (int i = 1; i < nn - 1; ++i)
      {
        /* Boundary conditions for this row. */
        u_[i][0] = one;
        p_[i][0] = zero;
        q_[i][0] = u_[i][0]; /* == one, but keep dependency as in original */

        /* Forward sweep: solve tridiagonal system along row i. */
        for (int j = 1; j < nn - 1; ++j)
        {
